const char* getNamedResource (const char* resourceNameUTF8, int& numBytes);
const char* getNamedResource (const char* resourceNameUTF8, int& numBytes)
{
    unsigned int hash = 0;

    if (resourceNameUTF8 != nullptr)
        while (*resourceNameUTF8 != 0)
            hash = 31 * hash + (unsigned int) *resourceNameUTF8++;

    switch (hash)
    {
        case 0xcc8ca173:  numBytes = 66468; return kick_wav;
        case 0x11004fc6:  numBytes = 88920; return snare_wav;
        case 0xe2b9a0fe:  numBytes = 10230; return hihat_closed_wav;
        case 0xb947dc1c:  numBytes = 112420; return hihat_open_wav;
        case 0x6e1d3254:  numBytes = 208544; return crash_wav;
        case 0xbbe9c27f:  numBytes = 173384; return tom_wav;
        default: break;
    }

    numBytes = 0;
    return nullptr;
}

